     1→import { useEffect, useRef } from "react";
     2→import { useLocation, useNavigate as useRouterNavigate } from "react-router-dom";
     3→import { registry } from "@/navigation/route-registry";
     4→import { buildColdStartBreadcrumb, buildBreadcrumbItem } from "@/navigation/breadcrumb-builder";
     5→import { isStackPrefixOf } from "@/navigation/navigate";
     6→import { useTabStore, selectActiveTab } from "@/stores/tab-store";
     7→
     8→/**
     9→ * Tab-Router Bridge
    10→ *
    11→ * Bidirectional sync between the tab store's navigation state and React Router.
    12→ * Uses URL-based deduplication to prevent infinite loops (more reliable than
    13→ * timing-based locks like requestAnimationFrame).
    14→ */
    15→export function TabRouterBridge() {
    16→  const routerNavigate = useRouterNavigate();
    17→  const location = useLocation();
    18→
    19→  // Track the last URL we pushed to each direction to deduplicate
    20→  const lastPushedToRouterRef = useRef<string | null>(null);
    21→  const lastPushedToStoreRef = useRef<string | null>(null);
    22→
    23→  // Get the active tab's current URL from the store
    24→  const activeTabId = useTabStore((s) => s.activeTabId);
    25→  const storeUrl = useTabStore((s) => {
    26→    const tab = selectActiveTab(s);
    27→    return tab?.navigationHistory[tab.historyIndex]?.url ?? null;
    28→  });
    29→
    30→  // Store actions
    31→  const pushNavigation = useTabStore((s) => s.pushNavigation);
    32→  const resetNavigation = useTabStore((s) => s.resetNavigation);
    33→
    34→  // Store -> Router: when store URL changes, update React Router
    35→  useEffect(() => {
    36→    if (!storeUrl) return;
    37→
    38→    const currentRouterPath = location.pathname + location.search;
    39→    const normalizedStoreUrl = registry.normalizeUrl(storeUrl);
    40→
    41→    if (normalizedStoreUrl === currentRouterPath) return;
    42→
    43→    // Skip if this store URL was set by our Router->Store sync
    44→    if (normalizedStoreUrl === lastPushedToStoreRef.current) {
    45→      lastPushedToStoreRef.current = null;
    46→      return;
    47→    }
    48→
    49→    lastPushedToRouterRef.current = normalizedStoreUrl;
    50→    routerNavigate(normalizedStoreUrl, { replace: true });
    51→  }, [storeUrl, routerNavigate, location.pathname, location.search]);
    52→
    53→  // Router -> Store: when React Router URL changes externally, update store
    54→  // NOTE: storeUrl is intentionally NOT in deps. This effect should only fire
    55→  // when the Router location changes (e.g. browser back/forward). Including
    56→  // storeUrl caused a race: store updates before Router, triggering this effect
    57→  // with stale location, which incorrectly reset the breadcrumb to the old path.
    58→  useEffect(() => {
    59→    if (!activeTabId) return;
    60→
    61→    const currentRouterUrl = location.pathname + location.search;
    62→    const normalizedUrl = registry.normalizeUrl(currentRouterUrl);
    63→
    64→    // Skip if this router URL was set by our Store->Router sync
    65→    if (normalizedUrl === lastPushedToRouterRef.current) {
    66→      lastPushedToRouterRef.current = null;
    67→      return;
    68→    }
    69→
    70→    // Read fresh from store to avoid stale closure
    71→    const activeTab = selectActiveTab(useTabStore.getState());
    72→    const currentState = activeTab?.navigationHistory[activeTab.historyIndex];
    73→
    74→    // Skip if URLs already match
    75→    const currentStoreUrl = currentState?.url ?? null;
    76→    if (currentStoreUrl && registry.normalizeUrl(currentStoreUrl) === normalizedUrl) return;
    77→
    78→    // Match against registry
    79→    const match = registry.match(normalizedUrl);
    80→    if (!match) {
    81→      // Unknown URL — don't update tab store, let React Router handle it
    82→      return;
    83→    }
    84→
    85→    lastPushedToStoreRef.current = normalizedUrl;
    86→
    87→    const currentStack = currentState?.breadcrumbStack ?? [];
    88→
    89→    if (isStackPrefixOf(currentStack, match)) {
    90→      // Smart push: existing stack is valid ancestor chain
    91→      const leaf = buildBreadcrumbItem(match.entry, match.params);
    92→      pushNavigation(activeTabId, normalizedUrl, leaf);
    93→    } else {
    94→      // Cold-start reset: deep link or direct URL entry
    95→      const stack = buildColdStartBreadcrumb(normalizedUrl);
    96→      resetNavigation(activeTabId, normalizedUrl, stack);
    97→    }
    98→  // eslint-disable-next-line react-hooks/exhaustive-deps
    99→  }, [location.pathname, location.search, activeTabId, pushNavigation, resetNavigation]);
   100→
   101→  return null;
   102→}
   103→

