     1→import { create } from "zustand";
     2→import { persist, createJSONStorage } from "zustand/middleware";
     3→import { buildColdStartBreadcrumb } from "@/navigation/breadcrumb-builder";
     4→import type { BreadcrumbStackItem } from "@/navigation/breadcrumb-builder";
     5→
     6→// ─── TabNavigationState (URL-based) ─────────────────────────────────────────
     7→
     8→export interface TabNavigationState {
     9→  url: string;
    10→  breadcrumbStack: BreadcrumbStackItem[];
    11→  activeNodeId?: string;
    12→  activeIndexPath?: string[];
    13→}
    14→
    15→export type PageViewMode = "skill" | "page";
    16→
    17→export interface PageTab {
    18→  id: string;
    19→  pinned: boolean;
    20→  historyIndex: number;
    21→  navigationHistory: TabNavigationState[];
    22→  viewMode?: PageViewMode;
    23→}
    24→
    25→export interface ClosedTabSnapshot {
    26→  tab: PageTab;
    27→  closedAt: number;
    28→  originIndex: number;
    29→}
    30→
    31→interface TabState {
    32→  tabs: PageTab[];
    33→  activeTabId: string | null;
    34→  recentlyClosedTabs: ClosedTabSnapshot[];
    35→}
    36→
    37→interface OpenTabInput {
    38→  pinned?: boolean;
    39→  viewMode?: PageViewMode;
    40→  navigationState: TabNavigationState;
    41→}
    42→
    43→export interface TabViewModel extends PageTab {
    44→  currentState: TabNavigationState | null;
    45→  currentUrl: string | null;
    46→  label: string;
    47→  titleKey?: string;
    48→  icon?: BreadcrumbStackItem["icon"];
    49→  descriptorId?: string;
    50→  meta?: BreadcrumbStackItem["meta"];
    51→  url: string | null;
    52→}
    53→
    54→interface TabActions {
    55→  openTab: (tab: OpenTabInput) => string;
    56→  closeTab: (tabId: string) => void;
    57→  closeOtherTabs: (tabId: string) => void;
    58→  closeTabsToRight: (tabId: string) => void;
    59→  setActiveTab: (tabId: string) => void;
    60→  pinTab: (tabId: string) => void;
    61→  unpinTab: (tabId: string) => void;
    62→  setViewMode: (tabId: string, mode: PageViewMode) => void;
    63→  moveTab: (fromIndex: number, toIndex: number) => void;
    64→  navigate: (tabId: string, url: string) => void;
    65→  pushNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
    66→  replaceNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
    67→  resetNavigation: (tabId: string, url: string, stack: BreadcrumbStackItem[]) => void;
    68→  replaceLocation: (tabId: string, next: TabNavigationState) => void;
    69→  pushLocation: (tabId: string, next: TabNavigationState) => void;
    70→  insertHistoryBeforeCurrent: (tabId: string, state: TabNavigationState) => void;
    71→  jumpToHistory: (tabId: string, historyIndex: number) => void;
    72→  goBack: (tabId: string) => void;
    73→  goForward: (tabId: string) => void;
    74→  canGoBack: (tabId: string) => boolean;
    75→  canGoForward: (tabId: string) => boolean;
    76→  getCurrentUrl: (tabId: string) => string | null;
    77→  getCurrentNavigationState: (tabId: string) => TabNavigationState | null;
    78→  findHistoryEntryByUrl: (tabId: string, url: string) => number;
    79→  closeAllTabs: () => void;
    80→  duplicateTab: (tabId: string) => string | null;
    81→  reopenClosedTab: () => string | null;
    82→  restoreTab: (tab: PageTab) => void;
    83→}
    84→
    85→const generateTabId = () =>
    86→  `tab-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
    87→const MAX_RECENTLY_CLOSED_TABS = 20;
    88→const MAX_NAVIGATION_HISTORY = 50;
    89→export const TAB_STORE_STORAGE_KEY = "viben-tab-store-v2";
    90→const TAB_STORE_VERSION = 2;
    91→
    92→function findLastPinnedIndex(tabs: PageTab[]): number {
    93→  for (let index = tabs.length - 1; index >= 0; index -= 1) {
    94→    if (tabs[index].pinned) {
    95→      return index;
    96→    }
    97→  }
    98→  return -1;
    99→}
   100→
   101→function buildStateFromUrl(url?: string): TabNavigationState {
   102→  const targetUrl = url ?? "/documents";
   103→  const stack = buildColdStartBreadcrumb(targetUrl);
   104→  return { url: targetUrl, breadcrumbStack: stack };
   105→}
   106→
   107→function isNavigationState(value: unknown): value is TabNavigationState {
   108→  if (!value || typeof value !== "object") return false;
   109→  const candidate = value as Partial<TabNavigationState>;
   110→  return typeof candidate.url === "string" && Array.isArray(candidate.breadcrumbStack);
   111→}
   112→
   113→function isPersistedPageTab(value: unknown): value is PageTab {
   114→  if (!value || typeof value !== "object") return false;
   115→  const candidate = value as Partial<PageTab>;
   116→  return typeof candidate.id === "string" && Array.isArray(candidate.navigationHistory);
   117→}
   118→
   119→function isPersistedSnapshot(value: unknown): value is ClosedTabSnapshot {
   120→  if (!value || typeof value !== "object") return false;
   121→  const candidate = value as Partial<ClosedTabSnapshot>;
   122→  return (
   123→    isPersistedPageTab(candidate.tab) &&
   124→    typeof candidate.originIndex === "number" &&
   125→    typeof candidate.closedAt === "number"
   126→  );
   127→}
   128→
   129→function normalizeTab(tab: PageTab): PageTab {
   130→  const navigationHistory = tab.navigationHistory.filter(isNavigationState);
   131→  const safeHistory = navigationHistory.length > 0 ? navigationHistory : [buildStateFromUrl("/workspace")];
   132→  const historyIndex = Math.min(
   133→    Math.max(tab.historyIndex ?? safeHistory.length - 1, 0),
   134→    safeHistory.length - 1
   135→  );
   136→
   137→  return {
   138→    id: tab.id,
   139→    pinned: Boolean(tab.pinned),
   140→    historyIndex,
   141→    navigationHistory: safeHistory,
   142→    viewMode: tab.viewMode,
   143→  };
   144→}
   145→
   146→function normalizeSnapshot(snapshot: ClosedTabSnapshot): ClosedTabSnapshot {
   147→  return {
   148→    tab: normalizeTab(snapshot.tab),
   149→    originIndex: snapshot.originIndex,
   150→    closedAt: snapshot.closedAt,
   151→  };
   152→}
   153→
   154→export function mergePersistedTabState(
   155→  persisted: Partial<TabState> | undefined,
   156→  current: TabState
   157→): TabState {
   158→  const tabs = (persisted?.tabs ?? []).filter(isPersistedPageTab).map(normalizeTab);
   159→  const tabIds = new Set(tabs.map((tab) => tab.id));
   160→  const activeTabId =
   161→    persisted?.activeTabId && tabIds.has(persisted.activeTabId)
   162→      ? persisted.activeTabId
   163→      : tabs[0]?.id ?? null;
   164→
   165→  return {
   166→    ...current,
   167→    tabs,
   168→    activeTabId,
   169→    recentlyClosedTabs: (persisted?.recentlyClosedTabs ?? [])
   170→      .filter(isPersistedSnapshot)
   171→      .map(normalizeSnapshot),
   172→  };
   173→}
   174→
   175→function cloneTabWithNewId(tab: PageTab, overrides?: Partial<PageTab>): PageTab {
   176→  return normalizeTab({
   177→    ...normalizeTab(tab),
   178→    ...overrides,
   179→    id: generateTabId(),
   180→  });
   181→}
   182→
   183→function createClosedSnapshot(tab: PageTab, originIndex: number): ClosedTabSnapshot {
   184→  return {
   185→    tab: normalizeTab(tab),
   186→    originIndex,
   187→    closedAt: Date.now(),
   188→  };
   189→}
   190→
   191→function pushClosedSnapshots(
   192→  stack: ClosedTabSnapshot[],
   193→  snapshots: ClosedTabSnapshot[]
   194→): ClosedTabSnapshot[] {
   195→  if (snapshots.length === 0) {
   196→    return stack;
   197→  }
   198→
   199→  return [...snapshots].reverse().concat(stack).slice(0, MAX_RECENTLY_CLOSED_TABS);
   200→}
   201→
   202→function restoreClosedTabIntoTabs(
   203→  tabs: PageTab[],
   204→  snapshot: ClosedTabSnapshot
   205→): { tabs: PageTab[]; restoredTab: PageTab } {
   206→  const restoredTab = cloneTabWithNewId(snapshot.tab);
   207→  const nextTabs = [...tabs];
   208→  const insertIndex = Math.max(0, Math.min(snapshot.originIndex, nextTabs.length));
   209→  nextTabs.splice(insertIndex, 0, restoredTab);
   210→  return { tabs: nextTabs, restoredTab };
   211→}
   212→
   213→export function getTabCurrentState(tab: PageTab): TabNavigationState | null {
   214→  return tab.navigationHistory[tab.historyIndex] ?? null;
   215→}
   216→
   217→export function getTabCurrentLeaf(tab: PageTab): BreadcrumbStackItem | null {
   218→  const current = getTabCurrentState(tab);
   219→  return current?.breadcrumbStack[current.breadcrumbStack.length - 1] ?? null;
   220→}
   221→
   222→export function getTabUrl(tab: PageTab): string | null {
   223→  const current = getTabCurrentState(tab);
   224→  return current?.url ?? null;
   225→}
   226→
   227→export function getTabViewModel(tab: PageTab): TabViewModel {
   228→  const currentState = getTabCurrentState(tab);
   229→  const leaf = getTabCurrentLeaf(tab);
   230→  const url = getTabUrl(tab);
   231→
   232→  return {
   233→    ...tab,
   234→    currentState,
   235→    currentUrl: url,
   236→    label: leaf?.label ?? url ?? "Untitled",
   237→    titleKey: leaf?.titleKey,
   238→    icon: leaf?.icon,
   239→    descriptorId: leaf?.pattern,
   240→    meta: leaf?.meta,
   241→    url,
   242→  };
   243→}
   244→
   245→function findHistoryEntryByUrlInHistory(
   246→  navigationHistory: TabNavigationState[],
   247→  historyIndex: number,
   248→  url: string
   249→): number {
   250→  for (let index = historyIndex - 1; index >= 0; index -= 1) {
   251→    if (navigationHistory[index].url === url) {
   252→      return index;
   253→    }
   254→  }
   255→  return -1;
   256→}
   257→
   258→
   259→// ─── Store ───────────────────────────────────────────────────────────────────
   260→
   261→export const useTabStore = create<TabState & TabActions>()(
   262→  persist(
   263→    (set, get) => ({
   264→      tabs: [],
   265→      activeTabId: null,
   266→      recentlyClosedTabs: [],
   267→
   268→      openTab: (tabData) => {
   269→        const id = generateTabId();
   270→        const newTab = normalizeTab({
   271→          id,
   272→          pinned: tabData.pinned ?? false,
   273→          navigationHistory: [tabData.navigationState],
   274→          historyIndex: 0,
   275→          viewMode: tabData.viewMode,
   276→        });
   277→
   278→        set((state) => ({
   279→          tabs: [...state.tabs, newTab],
   280→          activeTabId: id,
   281→        }));
   282→
   283→        return id;
   284→      },
   285→
   286→      closeTab: (tabId) => {
   287→        set((state) => {
   288→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   289→          if (tabIndex === -1) return state;
   290→
   291→          const recentlyClosedTabs = pushClosedSnapshots(
   292→            state.recentlyClosedTabs,
   293→            [createClosedSnapshot(state.tabs[tabIndex], tabIndex)]
   294→          );
   295→          const tabs = state.tabs.filter((tab) => tab.id !== tabId);
   296→          let activeTabId = state.activeTabId;
   297→
   298→          if (state.activeTabId === tabId) {
   299→            if (tabs.length === 0) {
   300→              activeTabId = null;
   301→            } else if (tabIndex >= tabs.length) {
   302→              activeTabId = tabs[tabs.length - 1].id;
   303→            } else {
   304→              activeTabId = tabs[tabIndex].id;
   305→            }
   306→          }
   307→
   308→          return { tabs, activeTabId, recentlyClosedTabs };
   309→        });
   310→      },
   311→
   312→      closeOtherTabs: (tabId) => {
   313→        set((state) => {
   314→          const snapshots = state.tabs
   315→            .map((tab, index) => ({ tab, index }))
   316→            .filter(({ tab }) => !tab.pinned && tab.id !== tabId)
   317→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   318→
   319→          return {
   320→            tabs: state.tabs.filter((tab) => tab.pinned || tab.id === tabId),
   321→            activeTabId: tabId,
   322→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   323→          };
   324→        });
   325→      },
   326→
   327→      closeTabsToRight: (tabId) => {
   328→        set((state) => {
   329→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   330→          if (tabIndex === -1) return state;
   331→
   332→          const snapshots = state.tabs
   333→            .map((tab, index) => ({ tab, index }))
   334→            .filter(({ tab, index }) => index > tabIndex && !tab.pinned)
   335→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   336→          const closingIds = new Set(snapshots.map((snapshot) => snapshot.tab.id));
   337→          const tabs = state.tabs.filter((tab) => !closingIds.has(tab.id));
   338→          const activeTabId = tabs.some((tab) => tab.id === state.activeTabId)
   339→            ? state.activeTabId
   340→            : tabId;
   341→
   342→          return {
   343→            tabs,
   344→            activeTabId,
   345→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   346→          };
   347→        });
   348→      },
   349→
   350→      setActiveTab: (tabId) => {
   351→        set({ activeTabId: tabId });
   352→      },
   353→
   354→      pinTab: (tabId) => {
   355→        set((state) => {
   356→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   357→          if (tabIndex === -1) return state;
   358→
   359→          const tab = state.tabs[tabIndex];
   360→          if (tab.pinned) return state;
   361→
   362→          const tabs = [...state.tabs];
   363→          tabs.splice(tabIndex, 1);
   364→
   365→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   366→          tabs.splice(insertIndex, 0, { ...tab, pinned: true });
   367→
   368→          return { tabs };
   369→        });
   370→      },
   371→
   372→      unpinTab: (tabId) => {
   373→        set((state) => {
   374→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   375→          if (tabIndex === -1) return state;
   376→
   377→          const tab = state.tabs[tabIndex];
   378→          if (!tab.pinned) return state;
   379→
   380→          const tabs = [...state.tabs];
   381→          tabs.splice(tabIndex, 1);
   382→
   383→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   384→          tabs.splice(insertIndex, 0, { ...tab, pinned: false });
   385→
   386→          return { tabs };
   387→        });
   388→      },
   389→
   390→      setViewMode: (tabId, mode) => {
   391→        set((state) => ({
   392→          tabs: state.tabs.map((tab) =>
   393→            tab.id === tabId ? { ...tab, viewMode: mode } : tab
   394→          ),
   395→        }));
   396→      },
   397→
   398→      moveTab: (fromIndex, toIndex) => {
   399→        set((state) => {
   400→          if (
   401→            fromIndex === toIndex ||
   402→            fromIndex < 0 ||
   403→            toIndex < 0 ||
   404→            fromIndex >= state.tabs.length ||
   405→            toIndex >= state.tabs.length
   406→          ) {
   407→            return state;
   408→          }
   409→
   410→          const tabs = [...state.tabs];
   411→          const [moved] = tabs.splice(fromIndex, 1);
   412→          tabs.splice(toIndex, 0, moved);
   413→          return { tabs };
   414→        });
   415→      },
   416→
   417→      navigate: (tabId, url) => {
   418→        get().pushLocation(tabId, buildStateFromUrl(url));
   419→      },
   420→
   421→      pushNavigation: (tabId, url, leaf) => {
   422→        const tab = get().tabs.find((entry) => entry.id === tabId);
   423→        const current = tab ? getTabCurrentState(normalizeTab(tab)) : null;
   424→        const currentStack = current?.breadcrumbStack ?? [];
   425→        const nextState: TabNavigationState = {
   426→          url,
   427→          breadcrumbStack: [...currentStack, leaf],
   428→        };
   429→        get().pushLocation(tabId, nextState);
   430→      },
   431→
   432→      replaceNavigation: (tabId, url, leaf) => {
   433→        const tab = get().tabs.find((entry) => entry.id === tabId);
   434→        const current = tab ? getTabCurrentState(normalizeTab(tab)) : null;
   435→        const currentStack = current?.breadcrumbStack ?? [];
   436→        const nextState: TabNavigationState = {
   437→          url,
   438→          breadcrumbStack: [...currentStack.slice(0, -1), leaf],
   439→        };
   440→        get().pushLocation(tabId, nextState);
   441→      },
   442→
   443→      resetNavigation: (tabId, url, stack) => {
   444→        const nextState: TabNavigationState = { url, breadcrumbStack: stack };
   445→        get().pushLocation(tabId, nextState);
   446→      },
   447→
   448→      replaceLocation: (tabId, next) => {
   449→        set((state) => ({
   450→          tabs: state.tabs.map((tab) => {
   451→            if (tab.id !== tabId) return tab;
   452→            const current = normalizeTab(tab);
   453→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex);
   454→            return normalizeTab({
   455→              ...current,
   456→              navigationHistory: [...baseHistory, next],
   457→              historyIndex: baseHistory.length,
   458→            });
   459→          }),
   460→        }));
   461→      },
   462→
   463→      pushLocation: (tabId, next) => {
   464→        set((state) => ({
   465→          tabs: state.tabs.map((tab) => {
   466→            if (tab.id !== tabId) return tab;
   467→            const current = normalizeTab(tab);
   468→            let history = [...current.navigationHistory.slice(0, current.historyIndex + 1), next];
   469→            let index = history.length - 1;
   470→            // Trim oldest entries if history exceeds limit
   471→            if (history.length > MAX_NAVIGATION_HISTORY) {
   472→              const excess = history.length - MAX_NAVIGATION_HISTORY;
   473→              history = history.slice(excess);
   474→              index = history.length - 1;
   475→            }
   476→            return normalizeTab({
   477→              ...current,
   478→              navigationHistory: history,
   479→              historyIndex: index,
   480→            });
   481→          }),
   482→        }));
   483→      },
   484→
   485→      insertHistoryBeforeCurrent: (tabId, next) => {
   486→        set((state) => ({
   487→          tabs: state.tabs.map((tab) => {
   488→            if (tab.id !== tabId) return tab;
   489→            const current = normalizeTab(tab);
   490→            const before = current.navigationHistory.slice(0, current.historyIndex);
   491→            const fromCurrent = current.navigationHistory.slice(current.historyIndex);
   492→            return normalizeTab({
   493→              ...current,
   494→              navigationHistory: [...before, next, ...fromCurrent],
   495→              historyIndex: before.length,
   496→            });
   497→          }),
   498→        }));
   499→      },
   500→
   501→      jumpToHistory: (tabId, historyIndex) => {
   502→        set((state) => ({
   503→          tabs: state.tabs.map((tab) => {
   504→            if (tab.id !== tabId) return tab;
   505→            const current = normalizeTab(tab);
   506→            return normalizeTab({
   507→              ...current,
   508→              historyIndex,
   509→            });
   510→          }),
   511→        }));
   512→      },
   513→
   514→      goBack: (tabId) => {
   515→        set((state) => ({
   516→          tabs: state.tabs.map((tab) => {
   517→            if (tab.id !== tabId) return tab;
   518→            const current = normalizeTab(tab);
   519→            if (current.historyIndex <= 0) return current;
   520→            return {
   521→              ...current,
   522→              historyIndex: current.historyIndex - 1,
   523→            };
   524→          }),
   525→        }));
   526→      },
   527→
   528→      goForward: (tabId) => {
   529→        set((state) => ({
   530→          tabs: state.tabs.map((tab) => {
   531→            if (tab.id !== tabId) return tab;
   532→            const current = normalizeTab(tab);
   533→            if (current.historyIndex >= current.navigationHistory.length - 1) {
   534→              return current;
   535→            }
   536→            return {
   537→              ...current,
   538→              historyIndex: current.historyIndex + 1,
   539→            };
   540→          }),
   541→        }));
   542→      },
   543→
   544→      canGoBack: (tabId) => {
   545→        const tab = get().tabs.find((item) => item.id === tabId);
   546→        return tab ? normalizeTab(tab).historyIndex > 0 : false;
   547→      },
   548→
   549→      canGoForward: (tabId) => {
   550→        const tab = get().tabs.find((item) => item.id === tabId);
   551→        if (!tab) return false;
   552→        const current = normalizeTab(tab);
   553→        return current.historyIndex < current.navigationHistory.length - 1;
   554→      },
   555→
   556→      getCurrentUrl: (tabId) => {
   557→        const tab = get().tabs.find((item) => item.id === tabId);
   558→        if (!tab) return null;
   559→        const current = getTabCurrentState(normalizeTab(tab));
   560→        return current?.url ?? null;
   561→      },
   562→
   563→      getCurrentNavigationState: (tabId) => {
   564→        const tab = get().tabs.find((item) => item.id === tabId);
   565→        return tab ? getTabCurrentState(normalizeTab(tab)) : null;
   566→      },
   567→
   568→      findHistoryEntryByUrl: (tabId, url) => {
   569→        const tab = get().tabs.find((item) => item.id === tabId);
   570→        if (!tab) return -1;
   571→        const current = normalizeTab(tab);
   572→        return findHistoryEntryByUrlInHistory(
   573→          current.navigationHistory,
   574→          current.historyIndex,
   575→          url
   576→        );
   577→      },
   578→
   579→      closeAllTabs: () => {
   580→        set((state) => {
   581→          const snapshots = state.tabs
   582→            .map((tab, index) => ({ tab, index }))
   583→            .filter(({ tab }) => !tab.pinned)
   584→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   585→          const tabs = state.tabs.filter((tab) => tab.pinned);
   586→          return {
   587→            tabs,
   588→            activeTabId: tabs[0]?.id ?? null,
   589→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   590→          };
   591→        });
   592→      },
   593→
   594→      duplicateTab: (tabId) => {
   595→        const state = get();
   596→        const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   597→        if (tabIndex === -1) return null;
   598→
   599→        const duplicatedTab = cloneTabWithNewId(state.tabs[tabIndex], {
   600→          pinned: false,
   601→        });
   602→
   603→        set((current) => {
   604→          const tabs = [...current.tabs];
   605→          tabs.splice(tabIndex + 1, 0, duplicatedTab);
   606→          return {
   607→            tabs,
   608→            activeTabId: duplicatedTab.id,
   609→          };
   610→        });
   611→
   612→        return duplicatedTab.id;
   613→      },
   614→
   615→      reopenClosedTab: () => {
   616→        let restoredTabId: string | null = null;
   617→
   618→        set((current) => {
   619→          const [nextSnapshot, ...restSnapshots] = current.recentlyClosedTabs;
   620→          if (!nextSnapshot) return current;
   621→
   622→          const restored = restoreClosedTabIntoTabs(current.tabs, nextSnapshot);
   623→          restoredTabId = restored.restoredTab.id;
   624→
   625→          return {
   626→            tabs: restored.tabs,
   627→            activeTabId: restored.restoredTab.id,
   628→            recentlyClosedTabs: restSnapshots,
   629→          };
   630→        });
   631→
   632→        return restoredTabId;
   633→      },
   634→
   635→      restoreTab: (tab) => {
   636→        const restoredTab = cloneTabWithNewId(tab);
   637→        set((state) => ({
   638→          tabs: [...state.tabs, restoredTab],
   639→          activeTabId: restoredTab.id,
   640→        }));
   641→      },
   642→    }),
   643→    {
   644→      name: TAB_STORE_STORAGE_KEY,
   645→      version: TAB_STORE_VERSION,
   646→      storage: createJSONStorage(() => ({
   647→        getItem: (name: string) => localStorage.getItem(name),
   648→        setItem: (name: string, value: string) => {
   649→          try {
   650→            localStorage.setItem(name, value);
   651→          } catch {
   652→            // QuotaExceededError — silently skip persist
   653→          }
   654→        },
   655→        removeItem: (name: string) => localStorage.removeItem(name),
   656→      })),
   657→      partialize: (state) => ({
   658→        tabs: state.tabs,
   659→        activeTabId: state.activeTabId,
   660→        recentlyClosedTabs: state.recentlyClosedTabs,
   661→      }),
   662→      merge: (persisted, current) => {
   663→        return {
   664→          ...current,
   665→          ...mergePersistedTabState(
   666→            persisted as Partial<TabState> | undefined,
   667→            current
   668→          ),
   669→        };
   670→      },
   671→    }
   672→  )
   673→);
   674→
   675→export const selectActiveTab = (state: TabState) =>
   676→  state.tabs.find((tab) => tab.id === state.activeTabId) ?? null;
   677→
   678→export const selectPinnedTabs = (state: TabState) =>
   679→  state.tabs.filter((tab) => tab.pinned);
   680→
