     1→// apps/desktop/src/navigation/navigate.ts
     2→import { registry } from "./route-registry";
     3→import { buildColdStartBreadcrumb, deriveAncestorsFromPrefix, type NavigateHeaders, type BreadcrumbStackItem } from "./breadcrumb-builder";
     4→import type { RouteMatch } from "./route-compiler";
     5→
     6→export type NavigateMethod = "push" | "replace" | "reset";
     7→
     8→/**
     9→ * Build the leaf BreadcrumbStackItem for a given URL.
    10→ * Used by the navigate function and can be used standalone.
    11→ */
    12→export function buildNavigateLeaf(url: string, headers?: NavigateHeaders): BreadcrumbStackItem {
    13→  const match = registry.match(url);
    14→  const fallbackLabel = url.split("/").filter(Boolean).pop() ?? url;
    15→
    16→  return {
    17→    id: headers?.id ?? url,
    18→    label: headers?.label ?? match?.title ?? fallbackLabel,
    19→    titleKey: match?.entry.titleKey,
    20→    icon: headers?.icon ?? match?.icon,
    21→    pattern: match?.pattern,
    22→    href: url,
    23→    sourceNodeId: headers?.sourceNodeId,
    24→    parentNodeId: headers?.parentNodeId,
    25→    meta: headers?.meta,
    26→  };
    27→}
    28→
    29→/**
    30→ * Unified navigate function — the primary API for all navigation.
    31→ *
    32→ * Called from use-desktop-routing hooks. Dispatches to the appropriate
    33→ * tab store action based on method.
    34→ *
    35→ * @param method - "push" appends leaf to stack, "replace" replaces top, "reset" rebuilds from cold-start
    36→ * @param url - The target URL (built via registry.build)
    37→ * @param headers - Optional overrides for the breadcrumb leaf (label, icon, meta, etc.)
    38→ * @param tabStore - Tab store actions (injected by hook to avoid module-level coupling)
    39→ */
    40→export function navigate(
    41→  method: NavigateMethod,
    42→  url: string,
    43→  headers: NavigateHeaders | undefined,
    44→  tabStore: {
    45→    activeTabId: string;
    46→    pushNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
    47→    replaceNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
    48→    resetNavigation: (tabId: string, url: string, stack: BreadcrumbStackItem[]) => void;
    49→  },
    50→): void {
    51→  const { activeTabId } = tabStore;
    52→  const leaf = buildNavigateLeaf(url, headers);
    53→
    54→  switch (method) {
    55→    case "push":
    56→      tabStore.pushNavigation(activeTabId, url, leaf);
    57→      break;
    58→    case "replace":
    59→      tabStore.replaceNavigation(activeTabId, url, leaf);
    60→      break;
    61→    case "reset": {
    62→      const stack = buildColdStartBreadcrumb(url, headers);
    63→      tabStore.resetNavigation(activeTabId, url, stack);
    64→      break;
    65→    }
    66→  }
    67→}
    68→
    69→/**
    70→ * Breadcrumb click handler — pops to the Nth breadcrumb item.
    71→ * Deduplicates: if a matching entry already exists in backward history, jumps there.
    72→ * Otherwise inserts before current position.
    73→ */
    74→export function popToBreadcrumb(
    75→  index: number,
    76→  tabStore: {
    77→    activeTabId: string;
    78→    getCurrentState: (tabId: string) => { breadcrumbStack: BreadcrumbStackItem[]; url: string } | null;
    79→    findHistoryEntryByUrl: (tabId: string, url: string) => number;
    80→    jumpToHistory: (tabId: string, historyIndex: number) => void;
    81→    insertHistoryBeforeCurrent: (tabId: string, state: { url: string; breadcrumbStack: BreadcrumbStackItem[] }) => void;
    82→  },
    83→): void {
    84→  const { activeTabId } = tabStore;
    85→  const current = tabStore.getCurrentState(activeTabId);
    86→  if (!current) return;
    87→
    88→  const targetItem = current.breadcrumbStack[index];
    89→  if (!targetItem?.href) return;
    90→
    91→  // Dedup: check if backward history already has this URL
    92→  const existingIndex = tabStore.findHistoryEntryByUrl(activeTabId, targetItem.href);
    93→  if (existingIndex >= 0) {
    94→    tabStore.jumpToHistory(activeTabId, existingIndex);
    95→    return;
    96→  }
    97→
    98→  // No match → insert new state before current (preserves forward history)
    99→  tabStore.insertHistoryBeforeCurrent(activeTabId, {
   100→    url: targetItem.href,
   101→    breadcrumbStack: current.breadcrumbStack.slice(0, index + 1),
   102→  });
   103→}
   104→
   105→/**
   106→ * Check whether the current breadcrumb stack is a valid prefix of the target match.
   107→ * Used by Tab-Router Bridge for smart push vs cold-start reset decision.
   108→ */
   109→export function isStackPrefixOf(stack: BreadcrumbStackItem[], match: RouteMatch): boolean {
   110→  if (stack.length === 0) return false;
   111→  const topPattern = stack[stack.length - 1]?.pattern;
   112→  if (!topPattern) return false;
   113→  const ancestors = deriveAncestorsFromPrefix(match.pattern);
   114→  return ancestors.includes(topPattern);
   115→}
   116→
   117→// Re-exports for convenience
   118→export { buildColdStartBreadcrumb, buildBreadcrumbItem, deriveAncestorsFromPrefix, type NavigateHeaders, type BreadcrumbStackItem } from "./breadcrumb-builder";
   119→export { registry } from "./route-registry";
